import React, { useState } from 'react';
import { Outlet, NavLink } from 'react-router-dom';

const TrangChuCuDan = () => {
    // Quản lý trạng thái người dùng
    const [user, setUser] = useState({
        hoTen: '',
        soPhong: '',
        isKhaiBao: false // Mặc định chưa khai báo sẽ hiện Form
    });

    const menuItems = [
        { name: 'Trung tâm thông báo', path: 'thong-bao', icon: '🔔' },
        { name: 'Thông tin cá nhân', path: 'thong-tin', icon: '👤' },
        { name: 'Hoá đơn & Phí', path: 'hoa-don', icon: '📄' },
        { name: 'Yêu cầu bảo trì', path: 'bao-tri', icon: '🔧' },
        { name: 'Quản lý phương tiện', path: 'phuong-tien', icon: '🚗' },
        { name: 'Đăng ký bãi đỗ', path: 'dang-ky-xe', icon: '🅿️' },
    ];

    const handleKhaiBao = (data) => {
        setUser({ ...data, isKhaiBao: true });
    };

    return (
        <div style={styles.container}>
            {/* SIDEBAR TRÁI */}
            <aside style={styles.sidebar} className="glass-sidebar">
                <div style={styles.logoBox}>
                    <h1 style={styles.logoText}>A&RMS</h1>
                    <span style={styles.logoSub}>RESIDENT</span>
                </div>

                <nav style={styles.nav}>
                    {menuItems.map((item, index) => (
                        <NavLink
                            key={index}
                            to={`/dashboard-cu-dan/${item.path}`}
                            style={({ isActive }) => ({
                                ...styles.navLink,
                                backgroundColor: isActive ? '#27ae60' : 'rgba(255,255,255,0.1)',
                                color: '#fff',
                                backgroundImage: isActive ? 'none' : "url('../assets/nen_nut_chinh.jpg')",
                                backgroundSize: 'cover'
                            })}
                        >
                            <span style={{ marginRight: '12px' }}>{item.icon}</span>
                            {item.name}
                        </NavLink>
                    ))}
                </nav>
            </aside>

            {/* VÙNG NỘI DUNG PHẢI */}
            <div style={styles.mainArea}>
                <header style={styles.header} className="glass-sidebar">
                    <div style={{ color: '#fff', fontWeight: '500' }}>Hệ thống cư dân thông minh</div>
                    <div style={styles.userProfile}>
                        <div style={{ textAlign: 'right', marginRight: '12px' }}>
                            <div style={{ fontWeight: 'bold' }}>{user.hoTen || 'Cư dân mới'}</div>
                            <div style={{ fontSize: '12px', opacity: 0.8 }}>{user.soPhong ? `Phòng ${user.soPhong}` : 'Chưa xác thực'}</div>
                        </div>
                        <div style={styles.avatar}></div>
                    </div>
                </header>

                <section style={styles.content}>
                    {!user.isKhaiBao ? (
                        <div className="glass-card fade-in" style={styles.formCard}>
                            <h2 style={{ color: '#2c3e50', marginBottom: '10px' }}>👋 Chào mừng bạn!</h2>
                            <p style={{ color: '#7f8c8d', marginBottom: '25px' }}>Vui lòng xác nhận thông tin để quản lý căn hộ.</p>
                            <input 
                                style={styles.input} 
                                placeholder="Họ và tên..." 
                                onChange={(e) => setUser({...user, hoTen: e.target.value})}
                            />
                            <input 
                                style={styles.input} 
                                placeholder="Số phòng (Vd: 101)..." 
                                onChange={(e) => setUser({...user, soPhong: e.target.value})}
                            />
                            <button 
                                style={styles.button}
                                onClick={() => handleKhaiBao(user)}
                            >
                                Truy cập ngay
                            </button>
                        </div>
                    ) : (
                        <div className="fade-in" style={{ width: '100%', height: '100%' }}>
                            <Outlet />
                        </div>
                    )}
                </section>
            </div>
        </div>
    );
};

const styles = {
    container: { display: 'flex', height: '100vh', padding: '15px', gap: '15px', boxSizing: 'border-box' },
    sidebar: { width: '280px', borderRadius: '30px', display: 'flex', flexDirection: 'column', padding: '20px' },
    logoBox: { textAlign: 'center', marginBottom: '40px' },
    logoText: { color: '#fff', margin: 0, fontSize: '32px', fontWeight: '900' },
    logoSub: { color: '#2ecc71', fontSize: '12px', letterSpacing: '3px', fontWeight: 'bold' },
    nav: { display: 'flex', flexDirection: 'column', gap: '12px' },
    navLink: { 
        padding: '15px 20px', borderRadius: '18px', textDecoration: 'none', 
        fontSize: '14px', fontWeight: '600', display: 'flex', alignItems: 'center', transition: '0.3s' 
    },
    mainArea: { flex: 1, display: 'flex', flexDirection: 'column', gap: '15px' },
    header: { height: '70px', borderRadius: '25px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 30px' },
    userProfile: { display: 'flex', alignItems: 'center', color: '#fff' },
    avatar: { 
        width: '45px', height: '45px', borderRadius: '50%', border: '2px solid #2ecc71',
        backgroundImage: "url('../assets/nen_ten_web.jpg')", backgroundSize: 'cover' 
    },
    content: { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center' },
    formCard: { width: '400px', padding: '40px', borderRadius: '30px', textAlign: 'center' },
    input: { 
        width: '100%', padding: '15px', marginBottom: '15px', borderRadius: '12px', 
        border: '1px solid #ddd', outline: 'none', boxSizing: 'border-box' 
    },
    button: { 
        width: '100%', padding: '15px', borderRadius: '12px', border: 'none', 
        backgroundColor: '#27ae60', color: '#fff', fontWeight: 'bold', cursor: 'pointer' 
    }
};

export default TrangChuCuDan;
